CREATE PROCEDURE [dbo].[FIRA_PR_CARGA_ST_CORRETORA]
AS

-- 1) cria tabela PADRAO baseada na estrutura atual da destino
IF OBJECT_ID(N'[dbo].[ST_CORRETORA_PADRAO]','U') IS NULL
BEGIN
    SELECT TOP (0) *
    INTO [dbo].[ST_CORRETORA_PADRAO]
    FROM [dbo].[ST_CORRETORA];
END;

-- 2) sincroniza schema (PADRAO -> DESTINO)
EXEC dbo.usp_sync_table_schema_add_alter_2012
  @src_schema = 'dbo',
  @src_table  = 'ST_CORRETORA_PADRAO',
  @dst_schema = 'dbo',
  @dst_table  = 'ST_CORRETORA',
  @execute    = 1,
  @allow_drop = 1;

-- 3) corpo original



/*********************	
	CARGA CORRETORA		
**********************/

---
--DELETE
TRUNCATE TABLE ST_CORRETORA


---
